        if cnt>bestcnt: best=(c,t0,l0,t1,r1); bestcnt=cnt
    c0,t0,l0,t1,r1=best
    ph=t1-t0+1; pw=r1-l0+1
    out=[[inp[r][c] for c in range(len(inp[0]))] for r in range(len(inp))]
    for c,t0,l0,t1,r1 in cs:
        h=t1-t0+1; w=r1-l0+1
        if (h,w)!=(ph,pw) or (c,t0,l0,t1,r1)==best:
            continue
        if (h,w)==(ph,pw):
            for a in range(h):
                for b in range(w):
                    out[t0+a][l0+b]= c if inp[best[0]+a][best[1]+b]==c0 else inp[best[0]+a][best[1]+b]
        else:
            for a in range(h):
                for b in range(w):
                    out[t0+a][l0+b]=0
    return out
