import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def cc(g):
    H,W=len(g),len(g[0]); seen=set(); res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; comp=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen or g[y][x]!=col: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W: st.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                res.append((col,min(ys),min(xs),max(ys),max(xs)))
    return res
def solve(inp):
    cs=cc(inp)
    bgc=None; src=None; best=-1
    for c,t0,l0,t1,r1 in cs:
        cnt=sum(1 for a in range(t0+1,t1) for b in range(l0+1,r1) if inp[a][b]==c)
        if cnt>best:
            best=cnt; src=(c,t0,l0,t1,r1)
    c0,t0,l0,t1,r1=src
    ph=t1-t0+1; pw=r1-l0+1
    pat=[[inp[t0+a][l0+b] for b in range(pw)] for a in range(ph)]
    out=[[inp[r][c] for c in range(len(inp[0]))] for r in range(len(inp))]
    # delete removed rects first
    for c,t0,l0,t1,r1 in cs:
        h=t1-t0+1; w=r1-l0+1
        if c!=c0 or (t0,l0)!=(t0,l0):
            pass
    for c,t0,l0,t1,r1 in cs:
        h=t1-t0+1; w=r1-l0+1
        if c==c0 and (t0,l0)==(src[1],src[2]): continue
        if (h,w)!=(ph,pw) or (c,t0,l0,t1,r1)!=src:
            for a in range(h):
                for b in range(w):
                    out[t0+a][l0+b]=0
    # stamp onto same-dims rects
    for c,t0,l0,t1,r1 in cs:
        h=t1-t0+1; w=r1-l0+1
        if c==c0 and (t0,l0)==(src[1],src[2]): continue
        if (h,w)!=(ph,pw): continue
        for a in range(h):
            for b in range(w):
                val=pat[a][b]
                out[t0+a][l0+b]= c if val==c0 else val
    return out
print(solve(G['Demo pair 3 input'])==G['Demo pair 3 output'])
